# Posterior-equivalence validation for physical S2Z group effects with
# coefficient- and group-specific scales.
#
# This local test compares the Stan program generated by the development brms
# build against standalone conventional models having exactly
#
#   log(sd_level[j, k]) = log(sd[k]) + sdlog[k] * z_scale[j, k],
#   z_scale[j, k] ~ normal(0, 1).
#
# The Gaussian case has correlated varying intercepts, slopes, and an
# interaction. The Student case has an intercept and slope with a diagonal
# scale matrix and the same one-per-group inverse-chi-square mixture used by
# brms. Both references put the intercept prior on the centered-X intercept,
# matching brms rather than an uncentered approximation.
#
# Run against an installed development build, for example:
#
#   R_LIBS=/path/to/development-library \
#     Rscript tests/local/tests.models-s2z-varying-scale.R
#
# Runtime controls (defaults shown):
#
#   BRMS_S2Z_VS_CASES=gaussian,student
#   BRMS_S2Z_VS_CHAINS=2
#   BRMS_S2Z_VS_WARMUP=400
#   BRMS_S2Z_VS_SAMPLING=400
#   BRMS_S2Z_VS_CORES=min(chains, physical cores)
#   BRMS_S2Z_VS_ADAPT_DELTA=0.98
#   BRMS_S2Z_VS_MAX_TREEDEPTH=12
#   BRMS_S2Z_VS_EQUIV_Z=7
#   BRMS_S2Z_VS_EQUIV_ABS=0.06
#   BRMS_S2Z_VS_EQUIV_REL=0.125
#   BRMS_S2Z_VS_MAX_RHAT=1.10
#   BRMS_S2Z_VS_MIN_BULK_ESS=40
#   BRMS_S2Z_VS_MIN_TAIL_ESS=50
#   BRMS_S2Z_VS_MAX_DIVERGENCES=0
#   BRMS_S2Z_VS_MAX_TREEDEPTH_HITS=0
#   BRMS_S2Z_VS_INVARIANT_TOL=1e-6
#   BRMS_S2Z_VS_REFRESH=0
#   BRMS_S2Z_VS_CACHE_DIR=
#   BRMS_S2Z_VS_OUTPUT_DIR=
#
# Posterior means, SDs, and 10%, 50%, and 90% quantiles are compared using
# both the propagated MCSE of the two independent fits and prespecified
# absolute-plus-relative tolerances. Set BRMS_S2Z_VS_OUTPUT_DIR to retain full
# CSV outcomes and their exact source provenance.

suppressPackageStartupMessages({
  library(brms)
  library(cmdstanr)
  library(posterior)
})

env_integer <- function(name, default, minimum = 1L) {
  value <- Sys.getenv(name, unset = "")
  if (!nzchar(value)) {
    return(as.integer(default))
  }
  out <- suppressWarnings(as.integer(value))
  if (length(out) != 1L || is.na(out) || out < minimum) {
    stop(name, " must be an integer >= ", minimum, call. = FALSE)
  }
  out
}

env_number <- function(name, default, minimum = -Inf) {
  value <- Sys.getenv(name, unset = "")
  if (!nzchar(value)) {
    return(as.numeric(default))
  }
  out <- suppressWarnings(as.numeric(value))
  if (length(out) != 1L || !is.finite(out) || out < minimum) {
    stop(name, " must be a finite number >= ", minimum, call. = FALSE)
  }
  out
}

script_path <- function() {
  arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  if (length(arg)) {
    return(normalizePath(sub("^--file=", "", arg[[1L]])))
  }
  normalizePath(file.path("tests", "local", "tests.models-s2z-varying-scale.R"))
}

